<?php
require_once __DIR__ . '/../../../app/bootstrap.php';
require_once __DIR__ . '/_helpers.php';
Auth::requireRole(['super_admin','owner']);
$db=Database::connect();opname_ensure_tables($db);$id=(int)($_POST['id']??0);
if(!is_post()||!CSRF::verify()){flash('error','Token keamanan tidak valid.');legacy_redirect('admin/stock-opname/index.php');}
$opname=opname_get($db,$id);if(!$opname||$opname['status']!=='draft'){flash('error','Sesi opname tidak ditemukan atau sudah final.');legacy_redirect('admin/stock-opname/index.php');}
try{
 $db->beginTransaction();$physical=$_POST['physical_stock']??[];$reasons=$_POST['reason']??[];$notes=$_POST['item_note']??[];$stmt=$db->prepare('SELECT id,system_stock FROM stock_opname_items WHERE opname_id=?');$stmt->execute([$id]);$raw=$stmt->fetchAll();$upd=$db->prepare('UPDATE stock_opname_items SET physical_stock=?,difference=?,reason=?,note=?,updated_at=NOW() WHERE id=? AND opname_id=?');foreach($raw as $it){$iid=(int)$it['id'];if(!array_key_exists($iid,$physical)||trim((string)$physical[$iid])==='')continue;$phys=max(0,(int)$physical[$iid]);$diff=$phys-(int)$it['system_stock'];$reason=trim((string)($reasons[$iid]??''));if($diff===0)$reason='match';$upd->execute([$phys,$diff,$reason?:'other',trim((string)($notes[$iid]??'')),$iid,$id]);}
 $items=opname_items($db,$id);$checked=array_filter($items,fn($it)=>$it['physical_stock']!==null);if(count($checked)<1)throw new Exception('Belum ada stok fisik yang diisi.');$branchId=(int)($opname['branch_id']??0)?:branch_current_id($db);
 $selectProduct=$db->prepare('SELECT id,name,stock FROM products WHERE id=? FOR UPDATE');$updateParent=$db->prepare('UPDATE products SET stock=?,updated_at=NOW() WHERE id=?');$mark=$db->prepare('UPDATE stock_opname_items SET system_stock=?,difference=?,adjusted_at=NOW() WHERE id=?');
 foreach($checked as $it){$pid=(int)$it['product_id'];$vid=(int)($it['variant_id']??0);$after=max(0,(int)$it['physical_stock']);if($vid>0){$before=marketplace_v16_variant_stock($db,$vid,$branchId,true);if($before!==$after){marketplace_v16_set_variant_stock($db,$vid,$branchId,$after,(int)($it['minimum_stock']??0));}marketplace_v16_sync_parent_stock($db,$pid,$branchId);$diff=$after-$before;try{$db->prepare("INSERT INTO stock_movements(product_id,user_id,branch_id,type,qty,stock_before,stock_after,reference_type,reference_id,note,created_at) VALUES(?,?,?,?,?,?,?,'stock_opname',?,?,NOW())")->execute([$pid,Auth::id(),$branchId,'stock_opname',abs($diff),$before,$after,$id,'Stock opname varian '.($it['variant_name']?:'').' - '.opname_reason_label($it['reason'])]);}catch(Throwable $e){}$mark->execute([$before,$diff,(int)$it['id']]);}
 else{$selectProduct->execute([$pid]);$p=$selectProduct->fetch();if(!$p)continue;$before=(int)$p['stock'];try{$q=$db->prepare('SELECT stock FROM product_branch_stocks WHERE branch_id=? AND product_id=? FOR UPDATE');$q->execute([$branchId,$pid]);$x=$q->fetchColumn();if($x!==false)$before=(int)$x;}catch(Throwable $e){}$diff=$after-$before;if($diff!==0){$db->prepare('INSERT INTO product_branch_stocks(branch_id,product_id,stock,minimum_stock,created_at) VALUES(?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE stock=VALUES(stock),updated_at=NOW()')->execute([$branchId,$pid,$after,0]);$isMain=$db->prepare('SELECT is_main FROM branches WHERE id=?');$isMain->execute([$branchId]);if((int)$isMain->fetchColumn()===1)$updateParent->execute([$after,$pid]);try{$db->prepare("INSERT INTO stock_movements(product_id,user_id,branch_id,type,qty,stock_before,stock_after,reference_type,reference_id,note,created_at) VALUES(?,?,?,?,?,?,?,'stock_opname',?,?,NOW())")->execute([$pid,Auth::id(),$branchId,'stock_opname',abs($diff),$before,$after,$id,'Stock opname '.$opname['code'].' - '.opname_reason_label($it['reason'])]);}catch(Throwable $e){}}$mark->execute([$before,$diff,(int)$it['id']]);}}
 opname_sync_totals($db,$id);$db->prepare("UPDATE stock_opnames SET status='finalized',finalized_at=NOW(),updated_at=NOW() WHERE id=?")->execute([$id]);Auth::log('finalize_stock_opname','Finalisasi stock opname '.$opname['code']);$db->commit();flash('success','Stock opname berhasil difinalisasi. Stok varian dan stok induk sudah disinkronkan.');legacy_redirect('admin/stock-opname/detail.php?id='.$id.'&success=1');
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();flash('error','Gagal finalisasi opname: '.$e->getMessage());legacy_redirect('admin/stock-opname/edit.php?id='.$id);}
